SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, d.icd_code, d.icd_version, COUNT(d.icd_code) AS diagnosis_count, SUM(CASE WHEN m.is_major = 1 THEN 1 ELSE 0 END) AS major_complication_count, SUM(CASE WHEN m.is_major = 1 THEN 5 ELSE 0 END) AS major_complication_score, lag(m.is_major) OVER (PARTITION BY p.subject_id ORDER BY a.admittime) AS previous_major_complication FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id AND a.hadm_id = d.hadm_id LEFT JOIN microbiologyevents m ON a.subject_id = m.subject_id AND a.hadm_id = m.hadm_id WHERE p.gender = 'M' AND p.anchor_age = 40 AND p.anchor_year = 2010 AND p.anchor_year_group = '35-45' AND d.icd_code = 'A01.0' AND d.icd_version = '4' GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, d.icd_code, d.icd_version ORDER BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, major_complication_score NULLS LAST;